'use strict';
// Expanded editorial portraits. The linked SEP/IEP surveys document each tradition.
// The introduction remains distinct from author-specific argument and historical context.
const portraitAdditions={};
function portrait(name,worldview,history){portraitAdditions[name]={worldview:worldview.split('|'),history:history.split('|')};}
portrait('Мартин Хайдеггер',
'Отправная точка «Бытия и времени» — повседневная вовлечённость. Сначала мы пользуемся инструментом, заботимся о близких, выполняем работу; лишь затем можем рассмотреть мир как набор объектов. Через эту смену исходной точки Хайдеггер пересматривает привычную картину изолированного сознания, которое должно доказать существование внешнего мира.|Человек уже получил язык, привычки и обстоятельства, но одновременно живёт возможностями. «Забота» связывает эту данность с проектами будущего. Подлинность означает принятие собственной конечности и ответственности за возможности, а не поиск скрытой неизменной личности. Тревога обнажает условность привычных ориентиров.|Поздний Хайдеггер исследует, как история, искусство и язык открывают разные способы присутствия вещей. Опасность техники он видит в привычке понимать всё, включая людей, как доступный запас ресурсов. Этот вопрос шире выбора между полезными и вредными устройствами.',
'Его проект вырос из феноменологии Гуссерля, чтения Аристотеля и христианских мыслителей. В университетской Германии после Первой мировой войны вопрос о конкретном существовании стал альтернативой отвлечённой теории познания.|В 1933 году Хайдеггер вступил в НСДАП и стал ректором Фрайбургского университета. Его поддержка режима и антисемитизм существенны для оценки связи философии, истории и политики; объяснить их общей атмосферой эпохи недостаточно.');
portrait('Иммануил Кант',
'Кант спрашивает, что делает опыт возможным. Ощущения дают материал, но пространство, время и категории задают форму, в которой мы встречаем предметы. Поэтому познание активно: оно не просто копирует внешний мир. Одновременно разум не получает права достоверно описывать всё, что лежит за пределами возможного опыта.|В этике главный вопрос — какой принцип моего поступка мог бы стать законом для каждого. Автономия означает подчинение разумно признанному закону, а не следование любому желанию. Человека нельзя использовать лишь как средство: у него есть собственные цели и достоинство.|Это разделяет два порядка вопросов: что можно знать и что следует делать. Ограничивая метафизические доказательства, Кант сохраняет пространство практического рассуждения о свободе. Его наследники спорят именно о том, насколько устойчиво это разделение.',
'Кант соединяет задачу обоснования ньютоновской науки с вызовом юмовского скептицизма. Просвещение делает публичное употребление разума самостоятельной ценностью; печать и образованная аудитория расширяют пространство спора.|Он работает в Кёнигсберге под властью прусской монархии. Напряжение между интеллектуальной самостоятельностью и политическим повиновением помогает понять его осторожное сочетание реформаторства и уважения к законному порядку.');
portrait('Платон',
'О красивых предметах и справедливых поступках можно спорить, потому что отдельные примеры не исчерпывают понятие. Платоновские формы дают устойчивый предмет мысли: знание требует большего, чем перечисление меняющихся впечатлений. Диалог заставляет проверить, не противоречит ли определение самому себе.|Этика связана с устройством души: желания и честолюбие нуждаются в разумном порядке. В «Государстве» справедливый полис рассматривается вместе со справедливым человеком. Воспитание превращается в политический вопрос, поскольку от него зависит, какие желания и представления граждане считают нормальными.|Значимость Платона не ограничивается одной доктриной форм. Он создаёт пространство, где вопрос можно пересматривать через возражения собеседника; разные диалоги усложняют исходные ответы. Позднейшая метафизика, христианская мысль и философия математики возвращаются к поставленным им проблемам.',
'Пелопоннесская война, политические перевороты в Афинах и казнь Сократа сделали ненадёжность публичного мнения острым личным и гражданским вопросом. Образ правления знающих связан с этим кризисом демократии.|Академия закрепила философское обучение как длительное совместное исследование. Однако идеал разумного порядка развивался внутри общества, где женщины, рабы и неграждане были исключены из полного политического участия.');
portrait('Аристотель',
'Объяснить вещь — значит понять, из чего она состоит, как устроена, благодаря чему возникает и к чему направлена её деятельность. Форма исследуется в конкретном существующем, а не только как отделённый образец. Поэтому его философия тесно связана с наблюдениями живой природы и классификацией способов объяснения.|В этике хорошая жизнь — деятельность на протяжении жизни, а не отдельное приятное чувство. Добродетель приобретается практикой; верное решение требует рассудительности, чувствительной к обстоятельствам. «Середина» означает уместную меру, а не арифметический компромисс.|Человек развивается среди других: дружба, воспитание и политические учреждения входят в условия благополучия. Это оставляет богатый язык для разговора о характере и общих благах, но связывает этику с вопросом о том, кому общество вообще предоставляет возможность хорошей жизни.',
'Аристотель учился в Академии Платона, позднее основал собственную школу — Ликей. Его работа приходится на изменение греческого мира при возвышении Македонии; он был наставником будущего Александра.|Полис остаётся образцом политического мышления, хотя его автономия ослабевает. Досуг гражданина, необходимый для обучения и политики, обеспечивался неравным распределением труда; это помогает увидеть социальные предпосылки и границы аристотелевского идеала.');
portrait('Рене Декарт',
'Методическое сомнение временно отбрасывает убеждения, которым можно противопоставить разумное сомнение. Сам акт мышления оказывается отправной достоверностью. Затем Декарт пытается восстановить знание о Боге и мире: сомнение служит строительству науки, а не постоянному отказу от неё.|Мыслящее и протяжённое он различает как разные виды субстанции. Материальные процессы предполагают механическое объяснение, тогда как сознание нельзя просто описать геометрией. Из этой попытки возникают одновременно программа математического естествознания и трудная проблема взаимодействия души и тела.',
'Математизация природы в XVII веке меняет образ убедительного знания: образцом становится доказательство. Схоластическая традиция сохраняет институциональную силу, а новые исследователи ищут независимый метод.|Религиозные конфликты и судьба Галилея делают публикацию натурфилософских взглядов рискованной. Декарт много лет живёт в Нидерландах; его осторожность в изложении сосуществует с радикализмом исходного сомнения.');
portrait('Георг Гегель',
'Сознание не получает готовую истину одним правильным методом. Его собственные представления сталкиваются с опытом, обнаруживают ограничения и преобразуются. Диалектика описывает такие переходы; её нельзя свести к механической последовательности «тезис — антитезис — синтез».|Свобода требует признания другими и институтов, в которых человек может действовать как свободный. Семья, гражданское общество и государство рассматриваются как разные формы совместной жизни. Поэтому история права и труда существенна для философии, а не служит внешним приложением.|Гегель стремится связать логику, природу и дух в систему. Это делает его мощным собеседником для Маркса и критической теории: они наследуют внимание к противоречиям и историчности, но оспаривают способ примирения мысли с действительностью.',
'Французская революция показала возможность радикально изменить политический порядок, а террор и войны — противоречия абстрактной свободы. Наполеоновские реформы и раздробленность Германии стали фоном поиска современных институтов.|Разрастание рынка создаёт богатство вместе с зависимостью и бедностью. Гегелевское гражданское общество — ранняя попытка осмыслить этот двойственный результат; его государство нельзя понимать лишь как ещё одно добровольное объединение покупателей.');
portrait('Карл Маркс',
'Маркс рассматривает экономические категории как отношения между людьми в исторически определённых условиях. Рабочая сила становится товаром, когда человек свободен продать её, но лишён самостоятельного доступа к средствам производства. Формальное равенство обмена поэтому может сосуществовать с эксплуатацией.|Капитал — движение стоимости, ориентированное на дальнейшее увеличение. Конкуренция заставляет менять технику и организацию труда; повседневная жизнь людей подчиняется силам, которые выглядят безличными. Товарный фетишизм обозначает ситуацию, когда общественные отношения воспринимаются как свойства вещей.|Освобождение предполагает изменение организации совместной жизни, а не только справедливое намерение отдельного человека. При этом анализ капитализма, прогнозы его будущего и программы политического действия — разные части наследия, требующие раздельной оценки.',
'Индустриализация, фабричная дисциплина и урбанизация сделали наёмный труд центральной социальной проблемой. Маркс соединяет немецкую философию с британской политической экономией и опытом французского социализма.|Революции 1848 года, эмиграция и рабочее движение определяют его политическую практику. Советские и другие позднейшие режимы обращались к его имени, но их институты нельзя автоматически принимать за прямое описание общества в текстах Маркса.');
portrait('Фридрих Ницше',
'Ницше исследует, как ценности возникают и какие формы жизни поддерживают. Генеалогия показывает, что моральные слова могут скрывать борьбу, обиду и способы самоутверждения. Вопрос меняется: нужно выяснять не только истинность убеждения, но и то, что оно делает с человеком.|«Смерть Бога» обозначает кризис прежнего основания ценностей. Нигилизм возникает, когда это основание утрачено, а привычка искать безусловную гарантию остаётся. Создание ценностей требует преобразования собственной жизни; оно не равнозначно произволу или праву сильного на любое действие.|Перспективизм обращает внимание на телесность, аффекты и положение познающего. Его задача — усложнить понимание объективности, а не просто объявить все суждения одинаковыми. Стиль афоризма позволяет сталкивать разные углы зрения и препятствует превращению мысли в готовую инструкцию.',
'Филологическое образование и спор о греческой культуре были исходной средой Ницше. В XIX веке историческая критика религии и престиж науки меняли положение христианства как общей картины мира.|Объединение Германии, массовая политика и национализм составляют фон его критики современности. Посмертные редакции и политические присвоения усложнили рецепцию; чтение должно различать опубликованные им книги и позднейшие компиляции заметок.');
portrait('Сёрен Кьеркегор',
'Решение о том, как жить, нельзя заменить знанием общей системы. Человек может понимать нравственное требование и всё же избегать выбора. Тревога связана с возможностью, а отчаяние — с нарушенным отношением к себе: нежеланием быть собой или попыткой опереться только на собственную волю.|Эстетическое, этическое и религиозное — разные способы существования, раскрываемые через голоса псевдонимов. Вера предполагает личное отношение к Богу, которое невозможно выполнить за другого. Светский читатель может учиться у его анализа выбора, не устраняя религиозную направленность проекта.',
'В датском обществе принадлежность к государственной церкви легко совпадала с обычной социальной респектабельностью. Кьеркегор выступает против христианства, которое стало привычкой без внутреннего решения.|Его полемика с систематической философией и прессой связана с растущей властью публичного мнения. Образ отдельного человека приобретает остроту именно там, где общество предлагает готовые роли и способы говорить от имени всех.');
portrait('Жан-Поль Сартр',
'Человек постоянно выходит за пределы уже данного: работы, прошлого, характера. Эти обстоятельства реальны, но не превращают будущий поступок в готовую вещь. «Дурная вера» возникает, когда мы скрываем от себя либо свободу, либо ограничения ситуации — например, полностью отождествляя себя с ролью.|Свобода не обещает успеха и не устраняет других людей. Чужой взгляд может превратить меня в объект оценки, но совместная жизнь требует действия среди чужих свобод. Позднее Сартр подробнее исследует, как социальные структуры и коллективные практики ограничивают индивидуальный проект.',
'Феноменология Гуссерля и чтение Хайдеггера дали ему средства анализа сознания и существования. Война, плен и оккупация Франции усилили вопрос о выборе в обстоятельствах, которых человек не выбирал.|Послевоенная публичная роль писателя, споры с коммунистами и деколонизация сделали «ангажированность» центральной темой. Между радикальной свободой ранних работ и коллективной историей поздних существует напряжение, а не простая смена лозунга.');
portrait('Симона де Бовуар',
'Свобода существует в ситуации: возможности людей неравны, и отвлечённое призывание «выбирать» может скрывать зависимость. Этика требует учитывать свободу других, поскольку собственный проект осуществим в общем человеческом мире.|Во «Втором поле» становление женщиной исследуется через воспитание, труд, тело, мифы и институты. Биология участвует в опыте, но сама по себе не определяет общественную судьбу. Категория Другого показывает, как мужской опыт получает статус нормы, а женский — исключения.',
'Бовуар работает на пересечении философии, литературы и послевоенных споров об ответственности. Ограничения образования, занятости и семейного права превращают вопрос об абстрактной свободе в вопрос о её условиях.|Позднейшее феминистское движение развивало и критиковало её подход. Классовые, расовые и колониальные различия показывают, почему даже критика «женской судьбы» нуждается в уточнении того, о чьём опыте идёт речь.');
portrait('Людвиг Витгенштейн',
'В «Логико-философском трактате» предложение рассматривается как изображение возможного положения дел. Философия должна прояснять границы осмысленного высказывания; этическую значимость жизни нельзя просто поместить среди описаний фактов.|В поздних работах внимание смещается к множеству языковых практик. Значение слова определяется его ролью в деятельности: просьба, обещание и измерение не обязаны иметь одну скрытую сущность. Философская трудность часто возникает, когда выражение отрывают от ситуации его применения.|Этот поворот меняет сам способ работы философа. Вместо универсальной объяснительной схемы предлагается рассматривать примеры, сравнивать употребления и распутывать соблазнительные аналогии. Между ранним и поздним периодами сохраняется стремление прояснить мысль, но средства существенно различаются.',
'Его работа соединяет культурную среду Вены с логическими исследованиями Рассела и Фреге. Опыт Первой мировой войны сопровождает создание ранней книги, хотя её логические задачи нельзя вывести из войны.|Учительство и возвращение в Кембридж предшествуют поздним исследованиям. В дальнейшем логический эмпиризм и философия обыденного языка по-разному использовали его идеи, поэтому «влияние Витгенштейна» означает несколько линий рецепции.');
portrait('Эдмунд Гуссерль',
'Восприятие всегда направлено на что-то: предмет дан с определённой стороны, в ожиданиях и связях с другими впечатлениями. Феноменология описывает это устройство данности. «Вынести за скобки» привычное допущение о мире — метод исследования опыта, а не утверждение, что мир исчезает.|Гуссерль различает логическую обоснованность и психологический факт убеждённости. В поздних работах он обращается к жизненному миру — донаучной среде значений, на которой строятся абстракции наук. Забывая её, наука рискует утратить связь со смыслом собственной деятельности.',
'Математическое образование и споры о психологизме определяют ранний проект строгого знания. Развитие экспериментальной психологии заставляло уточнять, можно ли объяснить логическую истину устройством человеческого мозга.|Кризис европейских институтов и нацистское преследование сопровождали его поздние годы. Его еврейское происхождение стало основанием для исключения из академической жизни, несмотря на давнее обращение в христианство.');
portrait('Мишель Фуко',
'Фуко исследует, как исторически складываются правила, позволяющие говорить о нормальности, безумии или преступлении как о предметах знания. Знание связано с учреждениями, процедурами наблюдения и классификацией. Это не означает, что любой факт произвольно выдуман властями.|Дисциплинарная власть действует через расписания, экзамены, пространства и нормирование тел. Она не только запрещает, но и производит привычки и типы субъекта. Поздний интерес к практикам себя показывает, что человек может работать над своим способом существования внутри исторически заданных отношений.',
'Послевоенный рост социальных наук, психиатрии и административного управления создаёт поле для его исследований. Архивы больниц и тюрем позволяют связать философские вопросы с конкретными процедурами и учреждениями.|Политические движения вокруг 1968 года и участие в работе о положении заключённых усилили практическую направленность анализа власти. Переход от общих теорий государства к локальным механизмам господства стал одним из его важнейших последствий.');
portrait('Ханна Арендт',
'Арендт различает поддержание жизни трудом, создание устойчивого мира вещей и политическое действие. Действовать — значит начинать новое среди людей, которые могут ответить непредсказуемо. Свобода поэтому проявляется в публичном участии, а не только в защищённой внутренней области.|Тоталитаризм разрушает множественность и способность судить. «Банальность зла» направляет внимание на бездумное исполнение роли: чудовищные действия возможны без демонической глубины личности. Это не снимает ответственности исполнителя и не делает преступление незначительным.',
'Бегство из нацистской Германии, опыт бесправия и эмиграция в США сделали гражданство и право иметь права личными вопросами. Её теория возникает из попытки понять тотальное господство, а не из абстрактного выбора лучшей конституции.|Наблюдение за процессом Эйхмана привело к ожесточённым спорам о суждении и ответственности. Послевоенная массовая политика одновременно давала надежду на новые начала и показывала опасность замены участия администрированием.');
portrait('Джон Ролз',
'Представьте выбор правил общества без знания, какое место достанется вам. «Завеса неведения» устраняет возможность подогнать принципы под собственные преимущества. Это мысленный способ проверить справедливость, а не описание реального исторического договора.|Базовые свободы имеют приоритет; социальное неравенство допустимо при справедливом равенстве возможностей и пользе для наименее обеспеченных. Позднее Ролз спрашивает, как эти принципы могут поддерживать граждане с разными религиозными и философскими убеждениями.',
'Проект формируется на фоне послевоенной конституционной демократии, государства благосостояния и споров о гражданских правах в США. Он предлагает альтернативу оправданию институтов одной суммой общественной полезности.|Реакции на Ролза разошлись: Нозик возражал против перераспределения, другие критики требовали учитывать глобальные связи, зависимости и историческую несправедливость. Именно эти возражения сделали его книгу узлом последующих дискуссий.');
portrait('Гераклит','Логос указывает на общий порядок, который не исчезает вместе с изменениями. Натяжение противоположных сил позволяет целому существовать: устойчивость не всегда означает неподвижность.|Этот ход важен для последующей диалектики. Однако Гераклит не предлагает готовой гегелевской системы: его краткие, образные высказывания связывают устройство космоса с ограниченностью человеческого понимания.','Ионийские города были пространством торговли, колонизации и политической конкуренции. В этой среде можно было сопоставлять разные обычаи и объяснения мира; философский спор постепенно становился альтернативой простому наследованию предания.');
portrait('Парменид','Если мыслить небытие как нечто существующее, рассуждение попадает в противоречие. Парменид делает требования мысли основанием радикального пересмотра опыта: возникновение, исчезновение и разделение перестают быть самоочевидными.|Последующие мыслители вынуждены ответить на этот вызов. Атомизм, учения о множестве элементов и платоновское различение уровней реальности по-разному пытаются сохранить возможность изменения без логической бессмыслицы.','Его поэма относится к греческой культуре Южной Италии. Форма откровения и строгая аргументация ещё сосуществуют: переход к философии не был мгновенным отказом от религиозного и поэтического языка.');
portrait('Демокрит','Атомы различаются порядком, положением и формой; их сочетания объясняют видимое многообразие. Цвет и вкус зависят от взаимодействия с воспринимающим, поэтому привычные качества требуют объяснения, а не простого переноса в основание мира.','Атомизм отвечает на споры о бытии, пустоте и движении, начатые элеатами. Это теоретическая модель природы, возникшая задолго до экспериментальной атомной физики и её приборов.');
portrait('Сократ','Вопрос «что такое справедливость?» отличается от просьбы назвать справедливый поступок. Проверяя ответы на противоречия, Сократ делает признание незнания началом нравственного исследования.|Философия превращается в способ жить среди людей: требование заботиться о душе нельзя выполнить одним накоплением сведений. Его пример объединяет исследование аргументов и личную ответственность за убеждения.','В афинских судах и собрании умение убеждать влияло на политическую судьбу. На фоне войны и переворотов публичное испытание авторитетов стало опасным; обвинение Сократа в нечестии и развращении молодёжи завершилось казнью в 399 году до н. э.');
portrait('Протагор','Человек судит из определённого положения, а гражданская добродетель формируется воспитанием. Практический вопрос состоит в том, можно ли улучшать суждения и совместную жизнь, не имея доступа к абсолютно нейтральной точке зрения.','Софисты обучали граждан речи и рассуждению за плату. Спрос на такое обучение связан с состязательными институтами полиса, а критика софистов — со страхом, что сила убеждения отделится от истины.');
portrait('Эпикур','Желания следует различать: естественные и необходимые нужды можно удовлетворить, тогда как погоня за славой и безграничным богатством не имеет конца. Разумный выбор удовольствий включает отказ от удовольствия, если за ним следует большая боль.|Атомистическое объяснение мира помогает ослабить страх перед вмешательством богов и посмертным наказанием. Дружба и небольшое сообщество дают практическую среду для спокойной жизни.','После завоеваний Александра мир греческого гражданина стал частью больших монархий. Эпикурейский Сад предложил устойчивую форму близкого общения там, где участие в политике уже не гарантировало контроля над собственной жизнью.');
portrait('Лукреций','Поэтическое объяснение природы служит освобождению от ужаса перед смертью. Если ощущение зависит от телесного соединения, распад этого соединения означает конец переживания, а не вечное переживание отсутствия жизни.','В поздней Римской республике греческая философия входила в латинскую литературу. Поэма переносит эпикурейские идеи к новой аудитории на фоне конкуренции элит и гражданских конфликтов.');
portrait('Зенон Китийский','Логика, физика и этика образуют взаимосвязанную программу: разумно оценивать поступки можно, понимая место человека в общем порядке. Внешние блага важны для выбора, но не делают человека нравственно хорошим автоматически.','Стоическая школа возникла в Афинах эллинистического периода. Образ общей разумной природы позволял мыслить принадлежность к человечеству шире границ одного полиса.');
portrait('Эпиктет','Между событием и реакцией находится суждение о событии. Упражнение состоит в проверке согласия, которое мы даём впечатлению: потеря репутации не обязана превращаться в утрату нравственной самостоятельности.','Эпиктет прошёл через рабство и преподавал в Римской империи. Его беседы записал Арриан; дисциплина внутреннего выбора формулируется в мире, где социальная власть над человеком могла быть почти неограниченной.');
portrait('Марк Аврелий','Повседневные напоминания возвращают внимание к краткости жизни, общей природе людей и исполнению текущего дела. Текст показывает философию как повторяемое упражнение: недостаточно однажды согласиться с правильной мыслью.','Императорские обязанности, военные походы и эпидемии составляют практический фон записей. Сопоставление личной этики с реальной имперской политикой позволяет увидеть границы философского самонаблюдения.');
portrait('Пиррон','Равная убедительность противоположных объяснений может заставить приостановить окончательный ответ. Жизнь продолжается на уровне привычек и явлений, даже если человек не объявляет скрытую природу вещей достоверно установленной.','Учение реконструируется через позднейшие свидетельства и последователей. Эллинистические школы соперничали не только теориями знания, но и обещанием спокойствия; скепсис стал одним из таких жизненных путей.');
portrait('Секст Эмпирик','Скептик противопоставляет доводу другой довод и исследует, не опирается ли доказательство на круг, бесконечный регресс или недоказанное допущение. Это делает скептицизм ресурсом проверки обоснований, даже для того, кто не принимает его как образ жизни.','Связь с медицинской эмпирической традицией важна для сочетания практического действия и осторожности в теориях. Сохранившиеся сочинения позднее стали одним из источников возрождения скептицизма в Европе Нового времени.');
portrait('Плотин','Единое не является ещё одной вещью среди вещей: оно мыслится как источник возможности единства вообще. Ум и Душа объясняют последующие уровни множественности, а внутреннее обращение человека связывает познание с преобразованием жизни.|Красота чувствительного мира может направлять к умопостигаемому порядку. Поэтому его философия не сводится к простому презрению к материи: важен переход от рассеянного восприятия к основанию единства.','В Римской империи III века пересекались греческие философские школы и разные религиозные практики. Плотин читает Платона в этой среде; Порфирий позднее организует его трактаты в «Эннеады».');
portrait('Прокл','Движение от причины к следствию сопровождается возвращением к основанию. Система связывает уровни реальности через последовательность аргументов, стремясь показать, как многообразие сохраняет зависимость от единства.','Позднеантичная афинская школа работала при усиливающемся христианском господстве. Через переводы и переработки прокловские схемы вошли в христианскую и исламскую философию, часто меняя исходную религиозную форму.');
portrait('Августин','Человек непосредственно обнаруживает себя как помнящего, желающего и сомневающегося. Исследование внутренней жизни становится философским методом; анализ времени показывает, что прошлое и будущее даны через память и ожидание.|Зло осмысляется как недостаток блага, а не самостоятельная равная Богу сила. Однако человек не может просто исправить себя одним знанием: воля способна разделяться между тем, чего желает, и тем, чего считает нужным желать. Отсюда центральность благодати.','Поздняя Римская империя переживала христианизацию и политическую нестабильность. Полемика с манихейством, донатизмом и пелагианством формировала его ответы о зле, церкви и свободе; падение Рима в 410 году стало поводом для «О граде Божьем».');
portrait('Фома Аквинский','Разум может исследовать природу и часть вопросов о Боге, но откровение сообщает то, что не выводится из философии. Истина не должна противоречить истине, поэтому различие методов не означает обязательной войны веры и рассуждения.|Вещь существует не только благодаря тому, чем она является: различение сущности и существования позволяет поставить вопрос об основании зависимого бытия. В этике естественный закон связывает разумное действие с человеческими благами и целями.','Университеты XIII века осваивали расширенный корпус Аристотеля и арабские комментарии. Споры о допустимости этих текстов делали синтез философии и богословия институциональной задачей, а не простым повторением церковного учения.');
portrait('Ансельм Кентерберийский','Вера побуждает искать понимание собственного содержания. Он пытается показать, что понятие Бога как предельного совершенства связано с существованием; именно переход от понятия к реальности стал предметом многовековых возражений.','Монастырская учёность предшествует развитой университетской схоластике. Борьба церковной и светской власти за назначения показывает, что рассуждения о высшем порядке существовали рядом с конфликтами вполне земных институтов.');
portrait('Уильям Оккам','Для объяснения общих высказываний необязательно постулировать отдельные общие сущности. Понятия и знаки позволяют говорить о многих единичных вещах; экономия предположений требует обоснования каждой дополнительной сущности.','Позднесредневековые споры о логике пересекались с конфликтами вокруг папской власти и францисканской бедности. Оккам применял критическое различение полномочий также к церковной политике.');
portrait('Пико делла Мирандола','Человеческая открытость к самоизменению связывается с духовным восхождением. Проект согласования разных учений предполагает, что истину можно искать на пересечении традиций, хотя эта открытость остаётся внутри религиозной картины мира.','Возрождение расширяет доступ к греческим, еврейским и другим текстам, а покровительство образованных элит поддерживает новые формы учёности. Одновременно церковный контроль ограничивает допустимые способы соединения традиций.');
portrait('Никколо Макиавелли','Политический поступок оценивается с учётом обстоятельств, силы и нестабильности. Удержание государства и республиканская свобода требуют понимания конфликта, а не только добрых качеств правителя; разные книги рассматривают разные политические задачи.','Итальянские войны и уязвимость городов-государств сделали внешнюю зависимость практической проблемой. Опыт флорентийской службы, падение республики и отстранение от политики придали анализу власти конкретную историческую почву.');
portrait('Мишель Монтень','Исследование себя показывает изменчивость суждений и зависимость привычного от воспитания. Скепсис ослабляет уверенность, с которой человек навязывает другим собственную норму; эссе становится формой мысли, сохраняющей возможность пересмотра.','Религиозные войны во Франции делали догматическую уверенность разрушительной политической силой. Гуманистическое чтение античности и сообщения о других культурах давали материал для сравнения европейских привычек с альтернативами.');
portrait('Джон Локк','Идеи возникают из ощущения и размышления о действиях ума. Анализ происхождения понятий помогает установить границы знания и отличить обоснованность от унаследованной уверенности.|Политическая власть требует согласия и ограничена задачей защиты прав. Право сопротивления ставит правителя под условие: институт существует ради людей, а не люди ради произвольной власти.','Научные и религиозные споры Англии XVII века соединялись с революциями и борьбой за ограничение монархии. При этом либеральные положения Локка сосуществовали с его участием в колониальном мире, что делает вопрос о границах провозглашённой свободы существенным.');
portrait('Дэвид Юм','Повторяемость событий приучает ожидать одно после другого, но необходимая связь не дана ощущению как отдельный предмет. Проблема причинности и индукции показывает разницу между привычкой ожидания и строгим доказательством.|Моральное суждение связано с чувствами и сочувствием; разум помогает понять обстоятельства, но сам по себе не создаёт цели. Человек оказывается природным и общественным существом, а не одним только вычисляющим рассудком.','Шотландское Просвещение развивалось в среде торговли, университетов и клубной культуры обсуждения. История и изучение человеческих нравов становились средствами объяснить общество без сведения каждого института к вечному замыслу.');
portrait('Фрэнсис Бэкон','Наблюдения следует организовывать так, чтобы исключать поспешные обобщения и привычные ошибки ума. «Идолы» обозначают устойчивые источники заблуждения — от особенностей восприятия до власти слов и авторитетных систем.','Рост технических практик и государственных проектов раннего Нового времени менял ожидания от знания. Бэкон связывает исследование с коллективной организацией и улучшением человеческих условий, предвосхищая институциональный идеал экспериментальной науки.');
portrait('Бенедикт Спиноза','Бог и природа не образуют две конкурирующие области причинности: всё существующее выражает единую субстанцию. Человек включён в тот же порядок, поэтому его желания и эмоции подлежат объяснению.|Свобода возникает через понимание необходимости и преобразование пассивных аффектов в более активную жизнь. Это отличается от возможности произвольно нарушать причинный порядок; политика должна создавать условия для разумного сотрудничества.','Торговая Голландская республика соединяла относительное многообразие верований с сильными религиозными конфликтами. Изгнание Спинозы из еврейской общины и полемика о свободе толкования Писания показывают пределы этой терпимости.');
portrait('Готфрид Лейбниц','Монады — простые центры восприятия; мир не исчерпывается протяжённой материей. Их согласованность объясняется предустановленной гармонией, а принцип достаточного основания требует спрашивать, почему существует именно этот порядок.|Истина о необходимом и истина о фактическом нуждаются в разных видах обоснования. Возможные миры позволяют обсуждать необходимость, случайность и выбор, даже если читатель не принимает богословский ответ самого Лейбница.','Европа после религиозных войн искала способы интеллектуального и политического согласования. Работа в математике, дипломатии и проектах универсального языка делала задачу общего рационального порядка частью практической деятельности Лейбница.');
portrait('Гоббс','Если нет общей силы, способной обеспечить договорённости, даже разумная забота о безопасности может вести к взаимному нападению. Суверенная власть прекращает эту неопределённость; легитимность объясняется защитой жизни, а не одной наследственной святостью правителя.','Английская гражданская война сделала распад общего порядка непосредственным опытом. Механистическая наука дала Гоббсу язык объяснения человеческих движений и страстей, а конфликт властей — материал для теории суверенитета.');
portrait('Жан-Жак Руссо','Общественное сравнение превращает зависимость от признания в источник несвободы. Развитие искусства и богатства поэтому не гарантирует нравственного улучшения; нужно исследовать, какие отношения они создают.|Общая воля относится к общему благу, а не просто к сумме частных желаний. Задача политического сообщества — сделать подчинение закону совместимым с самостоятельностью граждан; опасность заключается в том, кто получает право говорить от имени целого.','Неравенство сословного общества и культура публичного Просвещения формируют его вопросы. Женевский республиканский фон отличает Руссо от мыслителей, связывающих надежду исключительно с просвещённым монархом.');
portrait('Вольтер','Критика фанатизма направлена против принуждения, прикрытого абсолютной уверенностью. Ирония и историческое сравнение позволяют испытывать религиозные и политические авторитеты, не превращая любое сомнение в завершённую метафизическую систему.','Печать, переписка и салоны создали общеевропейскую аудиторию. Дела религиозно преследуемых людей показывали, как писатель мог вмешиваться в общественные конфликты, используя публичность как средство давления.');
portrait('Иеремия Бентам','Закон следует оценивать по последствиям для удовольствия и страдания затронутых людей. Такая постановка превращает привычное наказание или привилегию в вопрос об общественной пользе и требует учитывать интересы каждого.','Юридические реформы и рост административной способности государства создавали спрос на систематические критерии законодательства. Проект рационального управления одновременно открывал возможность улучшения институтов и усиления надзора.');
portrait('Джон Стюарт Милль','Удовольствия различаются не только количеством, но и качеством. Развитие способностей, индивидуальность и свободное обсуждение входят в хорошую жизнь; свобода защищает общество от самоуверенности большинства.|Принцип вреда ограничивает допустимое вмешательство в жизнь взрослого человека. Он не решает автоматически, что считать вредом, поэтому практические споры продолжаются внутри самого либерального подхода.','Индустриальная Британия обсуждала расширение избирательных прав, положение рабочих и женщин. Милль поддерживал реформы, но работал и внутри имперских институтов; универсальность свободы сталкивалась с колониальными исключениями.');
portrait('Мэри Уолстонкрафт','Зависимость и кажущаяся слабость женщин объясняются устройством воспитания, а не доказывают их природную неспособность к разуму. Равное образование становится условием самостоятельного нравственного суждения и гражданства.','Дебаты вокруг Французской революции провозгласили универсальные права, одновременно исключая женщин из политического равенства. Уолстонкрафт обращает язык Просвещения против этого внутреннего противоречия.');
portrait('Джудит Батлер','Гендерная устойчивость создаётся повторением общественно регулируемых действий. Перформативность не означает свободное переодевание по желанию: нормы предшествуют отдельному человеку, но повторяются с возможностью сдвига и переосмысления.','Феминизм и движения сексуальных меньшинств конца XX века спорили о том, кого представляет единая категория «женщины». Постструктуралистская критика идентичности позволяла расширять солидарность, одновременно усложняя её основания.');
portrait('Сильвия Федеричи','Домашний труд воспроизводит способность общества работать, хотя часто не оплачивается и выглядит природной обязанностью. Его анализ меняет границы экономического: забота, воспитание и контроль над телом входят в историю накопления.','Кампании за оплату домашнего труда и феминистские споры 1970-х годов сделали невидимую работу политической темой. Её исторические реконструкции связывают капитализм, колонизацию и гендерное насилие; конкретные причинные связи остаются предметом спора.');
portrait('Иоганн Фихте','«Я» обозначает активность, благодаря которой возможен опыт предмета и ограничение собственной деятельности. Исходный принцип не описывает эгоизм отдельного человека: он призван обосновать и знание, и практическую свободу.','Фихте радикализирует кантовский поворот к условиям опыта. Французская революция и наполеоновские войны делают вопросы самостоятельности, воспитания и национального сообщества частью его меняющегося публичного проекта.');
portrait('Фридрих Шеллинг','Природа должна обладать собственной продуктивностью, а не быть пассивным материалом сознания. Позднее свобода и возможность зла ставят предел построению мира как полностью прозрачной рациональной системы.','Романтизм, исследования живой природы и спор с Фихте формируют раннюю философию природы. Длительное развитие его мысли показывает внутреннее разнообразие немецкого идеализма, которое скрывает представление об одной школе после Канта.');
portrait('Артур Шопенгауэр','Тело дано и как объект среди объектов, и как непосредственное стремление. Этот двойной доступ становится основанием для понимания мира как представления и воли. Неутолимость желания объясняет постоянное возвращение страдания.|Эстетическое созерцание временно прерывает служение желанию, а сострадание ослабляет замкнутость в собственном интересе. Пессимизм здесь ведёт к этическому вопросу о страдании других, а не только к отрицательной оценке собственной жизни.','Он наследует Канту, спорит с оптимизмом систематического идеализма и читает доступные в Европе индийские тексты. Эта рецепция расширяла европейский кругозор, но происходила через ограниченные переводы и не равнялась знакомству со всеми индийскими традициями.');
portrait('Огюст Конт','Наука должна искать закономерные отношения явлений и отказываться от недоступных абсолютных причин. Социология завершает иерархию наук, а знание призвано поддерживать новый общественный порядок.','После революций и в ходе индустриализации вопрос о восстановлении согласия стал особенно острым. Конт переносит престиж естественных наук на общество; поздний проект религии человечества показывает, что он искал также нравственную интеграцию.');
portrait('Пётр Чаадаев','Оценка России становится способом спросить, что связывает народ с общечеловеческой историей. Христианская универсальность у него противопоставлена культурному самодовольству; в разных текстах пессимизм уступает возможности особой исторической задачи.','Публикация первого «Философического письма» в николаевской России вызвала репрессию и официальное объявление автора сумасшедшим. Спор о Европе поэтому был также спором о пределах допустимого публичного самоисследования.');
portrait('Владимир Соловьёв','Всеединство требует мыслить индивидуальное существование в связи с целым, не уничтожая личного достоинства. Нравственное совершенствование должно проявляться в отношениях и общественной жизни, а не только в частной религиозности.','Пореформенная Россия обсуждала границы церковной, государственной и общественной ответственности. Соловьёв отвечал и на позитивистскую веру в науку, и на национальную замкнутость религиозной мысли.');
portrait('Николай Бердяев','Объективация превращает живую свободу в безличные правила и принудительные структуры. Творчество выражает способность личности начинать новое; личность нельзя исчерпать её социальной функцией или принадлежностью к коллективу.','Переход от марксистской среды к религиозной философии, революция и высылка из Советской России в 1922 году дали его мысли опыт конкурирующих проектов освобождения. Эмиграция усилила критику как революционного принуждения, так и буржуазного обезличивания.');
portrait('Лев Шестов','Универсальная необходимость может оказаться бессильной перед единичной трагедией. Обращаясь к библейской вере, Шестов исследует возможность, которую разум заранее объявляет невозможной; спор касается самих прав рационального суда.','Русская литература и философия кризиса рубежа веков дают его размышлениям форму встречи с конкретной судьбой. Революция и эмиграция помещают этот протест против необходимости в опыт исторического разрыва.');
portrait('Фридрих Энгельс','Исследование жизни рабочего связывает экономическое устройство с жильём, здоровьем, семьёй и повседневной зависимостью. Поздние обобщения стремятся показать историчность институтов и их связь с материальным производством.','Наблюдения в промышленном Манчестере дали материал для ранней социальной критики. Сотрудничество с Марксом и редакторская работа над его наследием существенно повлияли на то, в каком виде марксизм вошёл в массовое движение.');
portrait('Антонио Грамши','Господство поддерживается школой, прессой, культурой и привычным здравым смыслом. Контргегемония требует длительной работы по организации альтернативного согласия; захват государственного аппарата сам по себе не завершает изменение общества.','Неудачи революционного движения и установление фашизма в Италии потребовали объяснить устойчивость капиталистического порядка. Тюремные условия определили фрагментарную форму его записей и осторожный язык политического анализа.');
portrait('Дьёрдь Лукач','Когда труд и отношения подчинены товарной форме, люди переживают созданные ими процессы как независимые законы вещей. Понятие целостности должно вернуть видимость связи между разрозненными фактами и общественным устройством.','Европейский марксизм после Первой мировой войны искал объяснение революции и её поражений. Собственный политический опыт Лукача и давление партийной ортодоксии показывают напряжение между философской критикой и дисциплиной движения.');
portrait('Чарльз Пирс','Чтобы уточнить смысл понятия, нужно спросить, какие мыслимые различия оно внесёт в опыт и действие. Истина при этом не сводится к удобству отдельного человека: исследование открыто исправлению со стороны сообщества.','Развитие экспериментальных наук, логики и измерительных практик в США определяет его взгляд на знание как длительную работу. Прагматизм первоначально возникает внутри вопросов о доказательстве и значении, а не как лозунг бытовой эффективности.');
portrait('Уильям Джеймс','Переживание не всегда укладывается в одну завершённую систему. Прагматический подход спрашивает, как принятие идеи изменяет опыт; религиозная вера исследуется также через её жизненные последствия и условия решения при недостатке доказательств.','Психология становилась самостоятельной экспериментальной дисциплиной, а религиозное многообразие США требовало сравнивать разные формы опыта. Джеймс соединял лабораторную работу с вниманием к личным кризисам и исключительным переживаниям.');
portrait('Джон Дьюи','Мысль начинается с затруднения и проверяет возможные решения в действии. Демократия — форма совместного обучения: гражданам нужны образование, обмен опытом и участие, а не только формальное право голосовать.','Урбанизация, массовая школа и индустриальные конфликты меняли американскую общественную жизнь. Прогрессивные реформы ставили задачу сделать образование средством участия в меняющемся мире, а не передачей неподвижного канона.');
portrait('Готлоб Фреге','Различение смысла и значения объясняет, почему два выражения об одном предмете могут сообщать разное знание. Логическая форма позволяет анализировать предложения точнее, чем грамматическое деление на подлежащее и сказуемое.|Основания арифметики должны зависеть от объективных законов мысли, а не от того, как люди фактически считают. Этот антипсихологизм стал одной из отправных точек аналитической философии.','Математика XIX века требовала строгого обоснования своих операций и понятий. Создание современной логики происходило внутри этой задачи, а не как простое усовершенствование правил красноречия.');
portrait('Бертран Рассел','Фраза может выглядеть так, будто называет предмет, хотя её логическая роль устроена иначе. Теория описаний показывает, как прояснение формы высказывания позволяет избежать лишних сущностей и ложных проблем.|Логический анализ претендует на точность, но Рассел постоянно пересматривал собственные ответы о знании и чувственных данных. Его пример показывает, что аналитическая философия — метод спора, а не один неизменный список убеждений.','Парадоксы оснований математики стимулировали работу Рассела и Уайтхеда. Войны XX века сделали его также публичным критиком милитаризма; математическая логика и политическая деятельность представляли разные стороны его жизни.');
portrait('Морис Мерло-Понти','Тело не только наблюдаемый механизм, но и способность ориентироваться и действовать. Восприятие уже содержит практическое понимание пространства; мысль вырастает из этой вовлечённости, а не добавляется к ней извне.','Феноменология встретилась с гештальтпсихологией и исследованиями нарушений восприятия. Послевоенные споры о марксизме и свободе усилили интерес к тому, как воплощённый человек действует в исторической ситуации.');
portrait('Фердинанд де Соссюр','Знак определяется отношениями различия: его значение не обязано происходить из естественного сходства с вещью. Разделение языка как системы и отдельного говорения позволяет исследовать правила, которыми пользуется носитель, не формулируя их явно.','Сравнительное языкознание XIX века изучало происхождение языков. Поворот к устройству системы в определённый момент дал гуманитарным наукам новый образец анализа; знаменитый курс был издан учениками по лекционным материалам.');
portrait('Клод Леви-Стросс','Сравнение мифов и родственных отношений выявляет преобразования одних схем в другие. Значение отдельного элемента обнаруживается через его место в системе, а не только через намерение рассказчика.','Антропология XX века переосмысляла представления о «примитивном» мышлении. Полевые исследования и освоение структурной лингвистики позволяли оспаривать интеллектуальное превосходство Европы, хотя сам структурный метод тоже критиковали за дистанцию от истории.');
portrait('Рудольф Карнап','Уточнение языка должно показывать, какие правила вывода и проверки мы принимаем. Часть метафизических споров можно заменить выбором явной системы выражения; поздний Карнап допускает множественность таких систем.','Венский кружок соединял логику с престижем новой физики и надеждой на научное просвещение. Нацизм разрушил эту интеллектуальную среду, а эмиграция перенесла многие дискуссии в англоязычные университеты.');
portrait('Мориц Шлик','Философия проясняет значение научных и повседневных утверждений, исследуя условия их проверки. Её задача отличается от выдвижения ещё одной картины мира поверх уже работающих наук.','Относительность и новые физические теории делали прежние представления о пространстве и знании спорными. Кружок вокруг Шлика превратил междисциплинарное обсуждение в устойчивую форму коллективной философской работы.');
portrait('Макс Хоркхаймер','Теория не находится вне общества: её вопросы, учреждения и применение тоже историчны. Критическая теория должна соединять объяснение господства с вопросом о возможности его преодоления.','Институт социальных исследований возник в среде межвоенного марксизма. Фашизм и эмиграция потребовали объяснить, почему рационализация и технический прогресс могут сопровождаться массовым варварством.');
portrait('Теодор Адорно','Разум становится инструментальным, когда спрашивает только о средствах и перестаёт исследовать цели. Культурное производство может приучать к готовым реакциям, воспроизводя подчинение в форме развлечения.|Негативная диалектика сохраняет внимание к тому, что понятие не охватывает. Страдание конкретного человека не должно исчезать в оправдывающей системе; искусство может сохранять опыт сопротивления готовому порядку.','Опыт нацистской катастрофы, эмиграции и массовой культуры США определяет его диагноз современности. После возвращения в Германию вопрос о просвещении стал вопросом о возможности жить и мыслить после Освенцима.');
portrait('Герберт Маркузе','Общество может воспроизводить подчинение, удовлетворяя потребности, которые само сформировало. Одномерность означает ослабление способности представить качественно иной способ жизни, даже при росте потребления.','Экономический подъём послевоенного Запада и интеграция рабочего класса заставляли переосмыслить классическую революционную надежду. Студенческие движения 1960-х годов увидели в Маркузе язык критики общества изобилия.');
portrait('Юрген Хабермас','Когда участники приводят доводы, они обращаются к возможности взаимного признания обоснованности. Эта структура общения даёт ориентир для критики манипуляции и принуждения, не требуя единой религии или картины хорошей жизни.','Послевоенная демократизация Германии требовала публичного обсуждения прошлого и новых оснований легитимности. Развитие средств массовой информации и бюрократии поставило вопрос о том, кто действительно способен участвовать в общественном разговоре.');
portrait('Альбер Камю','Абсурд возникает в отношении между желанием окончательного смысла и миром, который его не гарантирует. Камю исследует возможность жить ясно, не прибегая к обещанию окончательного примирения.|Бунт утверждает предел допустимого обращения с человеком и тем самым открывает солидарность. Если ради будущего совершенства разрешено всё, освобождение способно превратиться в новое убийственное господство.','Алжирское происхождение, война и работа в подпольной прессе придали его текстам конкретную политическую остроту. Споры о революционном насилии и колониальной Алжирской войне показывают также трудные ограничения его позиции.');
portrait('Франц Фанон','Колониальное господство входит в переживание тела, языка и самооценки. Освобождение требует менять не только юридический статус, но и отношения, в которых человек постоянно видит себя через унижающий взгляд.','Работа психиатром и участие в борьбе за независимость Алжира соединяют клиническое наблюдение с политикой. Фанон предупреждал, что национальная элита может воспроизвести зависимость после формального ухода колонизаторов.');
portrait('Эдвард Саид','Образ Востока формируется повторяющимися описаниями в литературе, науке и администрации. Исследование представлений выявляет, как право говорить о другом связано с возможностью распоряжаться его жизнью.','Палестинский опыт изгнания и работа в американском университете поставили автора между разными культурными и политическими средами. Деколонизация сделала авторитет европейского описания мира предметом систематической критики.');
portrait('Гаятри Спивак','Вопрос о голосе угнетённого касается каналов слышимости: кто переводит, отбирает и признаёт высказывание. Представлять другого политически и изображать его в теории — разные операции, но они могут поддерживать друг друга.','Постколониальные исследования сталкивались с классовыми и гендерными исключениями внутри национальных движений. Диалог с деконструкцией и марксизмом позволял критиковать и империю, и уверенность её академических критиков.');
portrait('Ганс-Георг Гадамер','Понимание начинается с предпосылок, которые человек получил вместе с языком и историей. Встреча с текстом может изменить эти предпосылки; «слияние горизонтов» обозначает процесс преобразования вопроса, а не исчезновение всех различий.','Гуманитарные науки искали собственное основание рядом с естественнонаучным методом. Чтение Хайдеггера и послевоенные споры о традиции поставили вопрос: как наследовать историю, сохраняя возможность критического разговора с ней?');
portrait('Поль Рикёр','Рассказ связывает события в осмысленную последовательность и помогает человеку понимать себя во времени. Идентичность включает и сохранение черт, и верность обещанию; она не сводится к неподвижному набору свойств.','Опыт войны и послевоенный диалог феноменологии, психоанализа и исследования языка формируют его герменевтику. Разные методы чтения — доверие смыслу и подозрение к скрытым мотивам — становятся взаимно необходимыми.');
portrait('Жак Деррида','Текст зависит от различий и повторяемости знаков: смысл никогда не присутствует как полностью изолированное содержание. Деконструкция показывает, что привилегированная сторона противопоставления нуждается в том, что объявляет вторичным.|Это меняет чтение философского наследия: важно исследовать исключения, напряжения и неустранимые следы другого внутри системы. Такой анализ не отменяет точности чтения и не даёт разрешения приписывать тексту любой смысл.','Французская интеллектуальная среда соединяла феноменологию со структурализмом. Колониальное происхождение автора из Алжира и последующие споры о языке, идентичности и университетском каноне придают его работе дополнительные политические измерения.');
portrait('Жиль Делёз','Понятия должны схватывать процессы становления, а не только распределять готовые вещи по классам. Различие продуктивно: новое не обязано быть простой копией или отрицанием уже существующего.','Французская философия после войны искала альтернативы господству единого субъекта и больших исторических схем. Сотрудничество с Феликсом Гваттари связало эти поиски с психиатрией, политикой после 1968 года и анализом капитализма.');
portrait('Роберт Нозик','Правомерность владения зависит от того, как собственность была приобретена и передана. Любая заранее установленная картина распределения нарушается свободными обменами; её поддержание требует постоянного вмешательства в выбор людей.','Либертарианская реакция на государство благосостояния развивалась рядом с возрождением нормативной теории у Ролза. Спор заставил уточнять разницу между справедливостью результата и справедливостью процесса, особенно при реальной истории захватов и принуждения.');
portrait('Донна Харауэй','Знание всегда производится из определённого положения, но это не освобождает от ответственности за его качество. Ситуативность требует показывать условия наблюдения; образ киборга оспаривает жёсткие границы между организмом, техникой и социальной ролью.','Феминистская критика науки встретилась с биотехнологиями и информационным трудом. Размывание привычных границ происходило практически — в медицине, производстве и военных исследованиях — прежде чем стало философской темой.');
portrait('Бернар Стиглер','Внешние носители памяти участвуют в формировании человеческого времени и внимания. Техническая среда может поддерживать обучение и одновременно лишать людей навыков и контроля над собственными желаниями.','Массовые медиа и цифровизация изменили хранение знания и экономику внимания. Стиглер соединяет чтение Хайдеггера и Гуссерля с вопросом о том, кому принадлежит организация повседневного опыта.');
portrait('Лучано Флориди','Информационная среда включает не только сообщения, но и отношения, действия и искусственных агентов. Этический анализ должен учитывать, как цифровое устройство меняет возможности человека и условия общего существования.','Распространение интернета, данных и автоматизированных решений расширило философию техники до вопросов информационной онтологии. Правила доступа, приватность и ответственность стали частью организации общества, а не узкой областью компьютерных специалистов.');
portrait('Конфуций','Человечность выращивается в отношениях: уважение, внимание к другому и ритуальная практика превращают внешнее правило во внутреннюю привычку. Достойный правитель действует примером, а не одним наказанием.|Возвращение к образцам прошлого означает нравственную работу в настоящем. Самообразование здесь имеет общественный смысл: меняясь сам, человек меняет качество связей в семье и государстве.','Ослабление порядка Чжоу и соперничество владений сделали восстановление доверия политической задачей. Странствующие учителя предлагали правителям разные способы упорядочить общество; поздняя государственная канонизация конфуцианства существенно преобразовала эту исходную ситуацию.');
portrait('Мэн-цзы','Спонтанное сочувствие указывает на нравственные задатки, но не гарантирует добродетели без воспитания. Человечная власть должна обеспечивать условия жизни народа; голод и страх разрушают возможность устойчивого нравственного поведения.','В эпоху Сражающихся царств советники конкурировали программами усиления государства. Мэн-цзы противопоставлял военному могуществу и выгоде правителя заботу о народе как основание политической легитимности.');
portrait('Будда','Непостоянство означает, что переживания, состояния тела и социальные положения не могут служить неизменной опорой. Привязанность к ним усиливает страдание; анализ «не-я» исследует, есть ли среди меняющихся составляющих опыта самостоятельный хозяин.|Освобождение связано с дисциплиной поведения, внимания и понимания. Это практический путь, а не одно согласие с отвлечённым тезисом о мире; община помогает поддерживать условия его осуществления.','Городской рост и развитие государств северной Индии сопровождались движениями странствующих аскетов. Буддийская община существовала благодаря отношениям монахов и мирян; поддержка купцов и правителей помогала распространять учение.');
portrait('Лао-цзы','Недеяние означает отказ от чрезмерного навязывания схемы происходящему. Мягкость, простота и ограничение желаний рассматриваются как способы не разрушить порядок собственной избыточной активностью.','«Дао дэ цзин» складывался в среде древнекитайских споров об управлении и порядке. Текст, традиционно связываемый с Лао-цзы, нельзя уверенно читать как биографическую исповедь одного установленного автора.');
portrait('Чжуан-цзы','Притчи заставляют менять масштаб и точку зрения: различие полезного и бесполезного зависит от того, кто оценивает. Мастерство показывает возможность действия, которое не держится на постоянном сознательном контроле.','Соревнование школ и политические конфликты древнего Китая создавали рынок готовых рецептов правильной жизни. Чжуан-цзы испытывает сами предпосылки такого поиска единственной обязательной меры.');
portrait('Умасвати','Путь освобождения связывает верное понимание, знание и поведение. Кармическая связанность души объясняет, почему мысль должна сопровождаться дисциплиной ненасилия и вниманием к последствиям собственных действий.','Джайнизм развивался через монашеские линии и мирские общины среди других индийских традиций освобождения. Систематическое изложение Умасвати создало общий предмет комментариев, хотя разные джайнские школы расходятся в его прочтении.');
portrait('Джаяраши Бхатта','Критика способов достоверного познания испытывает основания, на которые опираются конкурирующие школы. Если проверка надёжности восприятия или вывода требует уже принятого критерия, возникает опасность круга в доказательстве.','Индийская философия развивалась в публичных и текстовых спорах о средствах знания. Связь Джаяраши с чарвакой обсуждается исследователями: его радикальный скепсис нельзя безоговорочно приравнять к единой материалистической доктрине.');
portrait('Акшапада Гаутама','Ньяя различает средства знания и виды ошибок рассуждения. Восприятие, вывод, сравнение и свидетельство требуют анализа условий надёжности; публичное доказательство должно быть доступно проверке оппонента.|Освобождение связано с устранением заблуждения, поэтому логика имеет жизненную цель. Это позволяет сопоставлять ньяю с аналитической философией, не превращая сходство метода в утверждение о прямой исторической связи.','«Ньяя-сутры» принадлежат многослойной традиции составления и комментирования. Соперничество буддийских, джайнских и брахманских школ делало правила спора общей интеллектуальной проблемой.');
portrait('Ишваракришна','Пуруша — сознание-свидетель, пракрити — изменяющаяся природа, включая психические процессы. Освобождение наступает благодаря различению: ошибочно считать движение природы собственным неизменным существом.','«Санкхья-карика» сжато систематизирует длительную философскую традицию. Её схема взаимодействует с йогой и другими индийскими учениями, где знание об устройстве человека связано с практикой освобождения.');
portrait('Кумарила Бхатта','Понимание языка и нормативной силы ведийского предписания требует теории знания. Защита авторитетности Вед сопровождается подробными аргументами против буддийских объяснений значения и достоверности.','Миманса возникла вокруг истолкования ритуальных обязанностей, но развила самостоятельные исследования языка и познания. Спор шёл не между «религией» и «философией» в современном смысле, а между соперничающими рациональными обоснованиями практики.');
portrait('Шанкара','Повседневное различение субъекта и объектов скрывает недвойственное основание. Освобождающее знание раскрывает тождество атмана и брахмана; незнание здесь означает фундаментальную ошибку самоотождествления.|Мир опыта сохраняет практический статус, пока действует обычное познание. Поэтому тезис о недвойственности не равен простому бытовому отрицанию существования вещей или нравственных обязанностей.','Шанкара работает в комментаторской культуре, где Упанишады, «Брахма-сутры» и «Бхагавадгита» служат общими авторитетными текстами. Споры с буддистами и другими ведантистами показывают, насколько различными могли быть выводы из этого корпуса.');
portrait('Рамануджа','Мир и индивидуальные души реальны, но находятся в неразрывной зависимости от божественного целого. Единство допускает внутренние различия: личное отношение к Богу не должно исчезать в безличном недвойственном основании.|Преданность и благодать включены в путь освобождения. Его спор с адвайтой касается не только метафизики, но и статуса отношения между любящим и тем, к кому обращена любовь.','Южноиндийская храмовая культура и традиции бхакти создают практическую среду его веданты. Философское толкование канона связывается с живой религиозной поэзией и общинными формами поклонения.');
portrait('Нагарджуна','Если вещь возникает благодаря условиям, она не обладает полностью независимой собственной природой. Пустотность означает эту зависимость; сама пустотность тоже не становится отдельным абсолютным веществом.|Различение условной и предельной истины позволяет говорить и действовать в обычном мире, одновременно исследуя пределы наших категорий. Его аргументы испытывают крайности вечного самостоятельного бытия и полного небытия.','Махаяна переосмысляла буддийское наследие через новые тексты и идеал бодхисаттвы. Комментаторская рецепция Нагарджуны в Индии, Тибете и Восточной Азии создала несколько линий толкования, которые нельзя свести к одному современному лозунгу.');
portrait('Васубандху','Анализ переживания показывает, что объект всегда дан внутри определённого способа представления. Йогачара исследует привычки, кармические следы и различение субъекта и объекта, а не просто утверждает, что каждый человек выдумывает мир.|Корпус, связанный с Васубандху, включает и абхидхармическую систематизацию, и тексты йогачары. Между ними важны изменения задачи и метода, поэтому одна формула не охватывает всё наследие.','Буддийские монастырские центры поддерживали интенсивные споры о сознании и достоверности опыта. Переводы этих сочинений стали основой дальнейших дискуссий в Китае и Тибете.');
portrait('Мо-цзы','Беспристрастная забота требует учитывать пользу чужих семей и государств, а не только своих. Осуждение наступательной войны, расточительных ритуалов и наследственных привилегий связано с вопросом о последствиях для обычных людей.|Моистский подход соединяет нравственную требовательность с обсуждением критериев и практической эффективности. Он представляет самостоятельную альтернативу конфуцианскому акценту на дифференцированных отношениях.','Войны между древнекитайскими владениями делали расходы элит и защиту населения непосредственными проблемами. Моистские сообщества занимались также оборонительными практиками; поздняя традиция развивала логику и анализ языка.');
portrait('Хань Фэй','Порядок должен опираться на понятные стимулы, наказания и проверку исполнения, а не на ожидание добродетели чиновников. Правитель удерживает власть через управление назначениями и соответствием заявленной функции реальному результату.|Это меняет единицу политического анализа: важны механизмы поведения внутри системы. Однако эффективность контроля не отвечает сама по себе на вопрос, почему власть должна быть справедливой.','Сражающиеся царства усиливали армии, налоги и бюрократию. Проекты централизации потребовали методов, работающих за пределами личной верности и родственных связей; объединение при Цинь стало важнейшей средой рецепции подобных идей.');
portrait('Чжу Си','Принцип ли и материальная сила ци позволяют объяснять одновременно порядок и различие вещей. Нравственное исследование связано с «изучением вещей»: важно обнаруживать разумный строй и преобразовывать собственные привычки.|Работа над текстом и собой образует единую образовательную программу. Его комментарии делают философское самообразование доступным через организованный канон, который позднее приобретает государственную силу.','В эпоху Сун росли города, печать и образованная чиновничья среда. Ответ на буддийские и даосские вызовы сопровождался переустройством конфуцианского обучения; канонизация комментариев через экзамены сделала их социально влиятельными.');
portrait('Ван Янмин','Нравственное знание не исчерпывается накоплением внешних сведений. Если человек действительно знает должное, это должно проявиться в действии; разделение знания и поступка свидетельствует о неполноте понимания.|Врождённое знание добра требует очищения от эгоистических помех. Внутренний поворот не освобождает от общественных обязанностей, а меняет то, как человек работает над собой в их исполнении.','Минская образовательная система поощряла владение каноническими текстами. Ван Янмин спорил с превращением обучения в отвлечённую книжность; административная и военная служба делала единство знания и действия практической задачей.');
portrait('Ли Хван','Тончайшее различение нравственных чувств помогает понять, как принцип проявляется через конкретную психическую жизнь. Самовоспитание требует внимательности и уважительной сосредоточенности, а не одного знания правильной нормы.','Корейское государство Чосон организовывало образование и управление вокруг конфуцианских институтов. Спор о четырёх началах и семи чувствах показывает самостоятельную разработку китайского наследия в корейской философии.');
portrait('Ли И','Нравственный принцип действует через материально-психическую реальность ци. Уточнение этой связи поддерживает внимание к конкретным условиям воспитания и управления, не устраняя общего нормативного порядка.','В Чосон философские дискуссии были связаны с подготовкой чиновников и программами государственных реформ. Разногласия с линией Ли Хвана стали устойчивым интеллектуальным разделением, а не просто разницей личных темпераментов.');
portrait('Хуэйнэн','Пробуждение не обязательно понимается как постепенное накопление особых состояний. Важен непосредственный пересмотр привязанности к представлению о собственном уме; практика продолжается в обычной деятельности.|«Сутра помоста» соединяет учение с рассказом о передаче авторитета. Биографическая форма участвует в обосновании линии преемственности, поэтому её следует читать также как текст традиции.','Китайский буддизм развивался через переводы, монастыри и контакты с местными интеллектуальными практиками. Образ Хуэйнэна стал центральным для последующей истории чань, хотя текст оформлялся и перерабатывался после его жизни.');
portrait('Догэн','Сидячая медитация не просто средство получить награду пробуждения в будущем: практика уже выражает осуществление пути. Вопрос о времени и бытии включён в то, как человек полностью присутствует в конкретном действии.|Его тексты подробно переосмысляют повседневность и монастырскую дисциплину. Поэтому дзэн у Догэна нельзя свести к спонтанности без обучения и правил.','Путешествие в Китай и перенос чань в Японию происходили в условиях изменений религиозных институтов периода Камакура. Основание монастырской общины создало материальную среду для длительного воспроизводства его практики.');
portrait('Цонкапа','Пустотность должна пониматься вместе с зависимым возникновением: отрицание независимой сущности не отменяет причинность и нравственную ответственность. Точное рассуждение помогает избегать как овеществления абсолютного, так и нигилизма.|Путь сочетает аналитическое исследование, медитацию и дисциплину. Эта организация делает интеллектуальный спор частью религиозной практики, а не внешним противником духовного опыта.','Тибетские школы получили богатое индийское наследие через переводы и монастырское обучение. Реформаторская работа Цонкапы положила начало линии гелуг и влиятельной системе образовательных и практических учреждений.');
portrait('Аль-Фараби','Совершенное политическое сообщество должно направлять людей к счастью, понимаемому через развитие разума. Разные формы речи передают истину различным аудиториям; философия и религия рассматриваются в связи с воспитанием общества.','Переводческое движение арабоязычного мира предоставило доступ к греческой логике и политической философии. Многоязычная культура и дворовое покровительство позволили переработать это наследие под новые религиозные и политические вопросы.');
portrait('Ибн Сина','Сущность отвечает на вопрос, что представляет собой вещь, но сама по себе не гарантирует её существования. Различение возможного и необходимого бытия становится способом исследовать основание зависимого мира.|Мысленный опыт «парящего человека» направляет внимание на самосознание, которое не сводится к восприятию органов тела. Его философия соединяет метафизику, психологию и логику в систематический проект.','Работа при дворах Центральной Азии и Ирана связывала философию с медициной и политически нестабильной службой. Латинские переводы сделали авиценновские различения важными для университетской схоластики.');
portrait('Ибн Рушд','Комментарий к Аристотелю должен восстанавливать последовательность доказательства. Философское исследование и религиозный текст не обязаны противоречить друг другу, если различать способы понимания и уровень подготовленности аудитории.|Споры об интеллекте и связи индивидуального человека с общим познанием стали особенно влиятельны в латинской рецепции, где его тезисы часто приобретали новую полемическую роль.','Андалусская среда связывала философию, судейскую службу и медицину. Перемены покровительства при Альмохадах показывают зависимость интеллектуальной работы от двора; переводческие сети позднее перенесли её далеко за эти политические пределы.');
portrait('Аль-Газали','Критика философов испытывает их притязание доказать некоторые метафизические положения. Логика может быть полезна, даже если аргумент о вечности мира или причинной необходимости не выдерживает проверки.|Знание о правильном действии должно преобразовывать жизнь. Обращение к суфийской практике соединяет анализ пределов рассуждения с работой над намерением и духовной дисциплиной.','Преподавание в системе Низамийя помещало его в центр суннитской учёности и политики Сельджукской эпохи. Личный кризис и уход из публичного преподавания стали частью поиска основания религиозной уверенности.');
portrait('Шихаб ад-Дин Сухраварди','Свет служит языком степеней проявленности и знания. Непосредственное присутствие познающего у себя нельзя полностью заменить выводом из понятий; философия должна соединять доказательство с преобразованием восприятия.|Эта программа перерабатывает перипатетическую традицию, а не просто отвергает рациональность. Образный язык помогает ставить вопросы о самосознании и источнике очевидности.','Иранские интеллектуальные мотивы соединяются с арабоязычной философией и духовной практикой XII века. Политико-религиозный конфликт, завершившийся его казнью в Алеппо, показывает уязвимость автора внутри дворовой среды.');
portrait('Ибн Араби','Многообразие мира понимается через отношения божественного проявления. Воображение — не только произвольная фантазия: оно участвует в связи чувственного и духовного, позволяя рассматривать разные формы опыта.|Его тексты работают с парадоксами единства и различия. Позднейшие формулы «единства бытия» не следует превращать в одно плоское утверждение, будто различия между Богом, миром и человеком просто исчезают.','Странствия между западом и востоком исламского мира включали автора в широкие сети учёности и суфийских общин. Разнообразие последующих комментариев и критики показывает, что его наследие не стало единственной общепринятой доктриной суфизма.');
portrait('Мулла Садра','Существование первичнее отвлечённых сущностей и допускает степени интенсивности. Изменение затрагивает саму субстанцию, а не только внешние свойства; становление мира поэтому получает глубокий метафизический статус.|Философский аргумент, откровение и духовный опыт должны поддерживать друг друга. Эта интеграция продолжает спор с Ибн Синой и философией озарения, создавая новый синтез.','Сефевидский Иран институционализировал шиитскую учёность и поддерживал новые центры образования. В этой среде развитие исламской философии продолжалось спустя столетия после средневековых переводов, известных европейскому читателю.');
portrait('Нисида Китаро','Чистый опыт предшествует разложению на отдельного наблюдателя и наблюдаемый предмет. Позднее логика места исследует более широкое основание, внутри которого вообще возможны противопоставления субъекта и объекта.','Японские университеты осваивали европейскую философию на фоне быстрой модернизации. Нисида не просто переводил буддийские идеи на западный язык, а создавал новую систему в напряжении между интеллектуальными традициями и национальной политикой.');
portrait('Ниситани Кэйдзи','Нигилизм возникает, когда привычные основания смысла перестают поддерживать существование. Буддийская пустотность призвана преобразовать саму позицию, из которой человек требует гарантии собственного значения.','Японская модерность и опыт войны усилили спор о религии и европейском нигилизме. Связи Киотской школы с националистическим дискурсом требуют различать философскую аргументацию и исторические политические вмешательства её участников.');
portrait('Генри Одера Орука','Устная культура содержит не только коллективные верования, но и отдельных людей, способных критически обосновывать и пересматривать их. Философская мудрость требует выявлять аргумент, не приписывая всему народу одну неизменную систему.','После деколонизации спорили о том, должна ли африканская философия соответствовать европейскому письменному канону. Интервью с мудрецами в Кении расширяли признание интеллектуального авторства, одновременно ставя вопрос о роли интервьюера и перевода.');
portrait('Кваме Гьекье','Община необходима для становления личности, но не поглощает её права и самостоятельное суждение. Умеренный коммунитаризм пытается совместить обязанности взаимной помощи с достоинством конкретного человека.','Опыт независимой Ганы и исследование аканской мысли стали средой спора о традиции и современном государстве. Коммунитарность здесь обсуждается как аргументируемая позиция, а не как врождённое свойство всех африканских обществ.');
portrait('Несауалькойотль','В поэтической традиции науа краткость жизни и непрочность земного мира делают истину вопросом о возможной опоре среди изменения. Песнь, цветок и память выражают поиск смысла, который не обещает простой неуязвимости.','Связанные с его именем тексты переданы через позднейшую, в том числе колониальную запись. Придворная культура Тескоко и насилие завоевания важны для понимания и содержания, и того, какие свидетельства вообще сохранились.');
portrait('Энрике Дуссель','Этика начинается с требования услышать тех, чья жизнь исключена из признанного порядка. Система может выглядеть рациональной из центра и разрушительной для зависимых обществ; критика должна учитывать эту асимметрию.|Трансмодерность предполагает развитие альтернатив через диалог и освобождение, а не простое возвращение к нетронутому прошлому. Европейские понятия здесь становятся предметом переработки со стороны колониальной периферии.','Латиноамериканские диктатуры, зависимое развитие и политическая эмиграция формируют его проект. Диалог с Марксом и Левинасом соединяется с историей колонизации, ставя под вопрос рассказ о модерности как исключительно внутреннем достижении Европы.');
for(const p of philosophers){
 const extra=portraitAdditions[p.name];
 if(!extra)throw new Error('Missing expanded portrait: '+p.name);
 p.worldview=[p.notes[0],...extra.worldview];
 p.historicalContext=extra.history.length>1?extra.history:[currents.find(c=>c.id===p.schools[0]).context,...extra.history];
}
